/**
 * Syncs the site's design system into the Elementor plugin.
 *   bun scripts/build-elementor-plugin.tsx
 * - src/styles/lc/*.css  -> assets/css/labconnect.css (every selector scoped under `.lc-w`)
 * - lucide icons         -> includes/class-icons.php
 * Never hand-edit the two generated files; edit the sources and re-run.
 */
import postcss from "postcss";
import { readFileSync, writeFileSync } from "node:fs";
import { createElement } from "react";
import { renderToStaticMarkup } from "react-dom/server";
import * as L from "lucide-react";

const PLUGIN = "elementor-plugin/labconnect-widgets";
const SOURCES = ["tokens", "atoms", "molecules", "sections"].map((n) => `src/styles/lc/${n}.css`);

// ---------- CSS ----------
const banner = `/* AUTO-GENERATED from src/styles/lc/*.css by scripts/build-elementor-plugin.tsx — do not edit. */\n`;
let css = "";
for (const file of SOURCES) {
  const root = postcss.parse(readFileSync(file, "utf8"));
  root.walkRules((rule) => {
    const parent = rule.parent as postcss.AtRule | undefined;
    if (parent?.type === "atrule" && /keyframes/.test(parent.name)) return;
    if (rule.selectors.every((s) => s.includes(".lc-lib"))) {
      rule.remove();
      return;
    }
    rule.selectors = rule.selectors.map((s) => {
      if (s.startsWith(":root")) return s;
      if (s.includes(".lc-root")) return s.replaceAll(".lc-root", ".lc-w");
      return `.lc-w ${s}`;
    });
  });
  root.walkComments((c) => {
    if (c.text.includes("Widget library page")) c.remove();
  });
  css += `\n/* ===== ${file} ===== */\n` + root.toString();
}
writeFileSync(`${PLUGIN}/assets/css/labconnect.css`, banner + css);

// ---------- Icons ----------
const icons: Record<string, [keyof typeof L, string]> = {
  "arrow-right": ["ArrowRight", "Arrow right"],
  "arrow-up-right": ["ArrowUpRight", "Arrow up-right"],
  "badge-check": ["BadgeCheck", "Badge check"],
  calendar: ["CalendarClock", "Calendar"],
  file: ["FileText", "Document"],
  flask: ["FlaskConical", "Flask"],
  heart: ["HeartPulse", "Heart pulse"],
  megaphone: ["Megaphone", "Megaphone"],
  monitor: ["MonitorSmartphone", "Monitor + phone"],
  pen: ["PenLine", "Pen"],
  share: ["Share2", "Share"],
  sparkles: ["Sparkles", "Sparkles"],
  stethoscope: ["Stethoscope", "Stethoscope"],
  zap: ["Zap", "Zap"],
  check: ["Check", "Check"],
  star: ["Star", "Star"],
  menu: ["Menu", "Menu"],
  x: ["X", "Close"],
  microscope: ["Microscope", "Microscope"],
  pill: ["Pill", "Pill"],
  syringe: ["Syringe", "Syringe"],
  activity: ["Activity", "Activity"],
  hospital: ["Hospital", "Hospital"],
  "shield-check": ["ShieldCheck", "Shield check"],
  award: ["Award", "Award"],
  users: ["Users", "Users"],
  "book-open": ["BookOpen", "Book"],
  "graduation-cap": ["GraduationCap", "Graduation cap"],
  image: ["Image", "Image"],
  layout: ["LayoutTemplate", "Layout"],
  "trending-up": ["TrendingUp", "Trending up"],
  target: ["Target", "Target"],
  clock: ["Clock", "Clock"],
  phone: ["Phone", "Phone"],
  mail: ["Mail", "Mail"],
  "map-pin": ["MapPin", "Map pin"],
  "message-circle": ["MessageCircle", "Chat bubble"],
  globe: ["Globe", "Globe"],
  "chevron-right": ["ChevronRight", "Chevron right"],
  plus: ["Plus", "Plus"],
};
const rows = Object.entries(icons).map(([name, [comp, label]]) => {
  const C = L[comp] as unknown as L.LucideIcon;
  if (!C) throw new Error(`Missing lucide icon ${comp}`);
  const svg = renderToStaticMarkup(createElement(C));
  const inner = svg.replace(/^<svg[^>]*>/, "").replace(/<\/svg>$/, "");
  return { name, label, inner };
});
const php = `<?php
// AUTO-GENERATED by scripts/build-elementor-plugin.tsx from lucide-react — do not edit.
namespace LCW;

if ( ! defined( 'ABSPATH' ) ) { exit; }

class Icons {
\tconst LABELS = [
${rows.map((r) => `\t\t'${r.name}' => '${r.label}',`).join("\n")}
\t];

\tconst SVG = [
${rows.map((r) => `\t\t'${r.name}' => '${r.inner}',`).join("\n")}
\t];

\tpublic static function options() { return self::LABELS; }

\tpublic static function svg( $name, $class = '', $stroke = 2 ) {
\t\tif ( ! isset( self::SVG[ $name ] ) ) { return ''; }
\t\t$cls = '' !== $class ? ' class="' . esc_attr( $class ) . '"' : '';
\t\treturn '<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="' . (float) $stroke . '" stroke-linecap="round" stroke-linejoin="round"' . $cls . ' aria-hidden="true">' . self::SVG[ $name ] . '</svg>';
\t}
}
`;
writeFileSync(`${PLUGIN}/includes/class-icons.php`, php);
console.log(`css ${css.length} chars, ${rows.length} icons`);
